export const RENTRACK_SCRIPT = "<script>\n/* Renaud featured tracking.\n * Companion to the existing v5.5 GoatCounter action events script.\n * This file does not replace v5.5; it adds the Renaud partner events:\n *   Event 1  renaud-card-view   /_events/renaud-card-view/<surface>/<host slug>\n *   Event 2  renaud-card-click  /_events/renaud-card-click/<surface>/<host slug>\n *   Event 3  renaud-call        /_events/renaud-call/<surface>/<page slug>\n *   Supp.    renaud-website     /_events/renaud-website/ytp-profile/<page slug>\n * Surface values: ytp-card-category, ytp-card-listing, ytp-hub, ytp-profile.\n * The generator should set data-surface on the card (authoritative).\n * The inference below is a fallback only. No personal data is sent.\n * Honest limits: a card view means the card entered the viewport at\n * 50 percent visibility once; it does not prove anyone read it.\n * A call event means the tel link was tapped, not that a call connected.\n */\n(function () {\n  var PROFILE_SLUG = \"natural-skincare/renaud-naturals-loveland\";\n\n  function fire(path) {\n    try {\n      if (!window.goatcounter || !window.goatcounter.count) return;\n      window.goatcounter.count({ path: path, event: true, title: path });\n    } catch (e) {}\n  }\n\n  function pageSlug() {\n    return window.location.pathname.replace(/^\\/+|\\/+$/g, \"\");\n  }\n\n  function inferSurface(slug) {\n    /* Town hub or state page: /colorado/westminster/ or /colorado/ */\n    if (/^[a-z-]+\\/[a-z-]+$/.test(slug) && slug.indexOf(\"/\") === slug.lastIndexOf(\"/\")) {\n      var first = slug.split(\"/\")[0];\n      /* Single listing pages also have two segments, so hubs are matched\n       * by the state segment list used by the generator. When in doubt,\n       * the generator supplied data-surface wins and this never runs. */\n      var states = [\"colorado\", \"arizona\", \"california\", \"texas\", \"florida\", \"nevada\", \"utah\", \"wyoming\", \"montana\", \"idaho\", \"oregon\", \"washington\", \"new-mexico\", \"oklahoma\", \"kansas\", \"nebraska\", \"south-dakota\", \"north-dakota\", \"minnesota\", \"iowa\", \"missouri\", \"arkansas\", \"wisconsin\", \"illinois\", \"michigan\", \"indiana\", \"ohio\", \"kentucky\", \"tennessee\", \"louisiana\", \"mississippi\", \"alabama\", \"georgia\", \"alaska\", \"hawaii\", \"puerto-rico\"];\n      if (states.indexOf(first) !== -1) return \"ytp-hub\";\n      return \"ytp-card-listing\";\n    }\n    /* Category in town: /med-spas/colorado/westminster/ (3 segments) */\n    if (slug.split(\"/\").length === 3) return \"ytp-card-category\";\n    return \"ytp-card-listing\";\n  }\n\n  function firstTouchSrc(value) {\n    try {\n      var k = \"ytp_renaud_src\";\n      if (!window.sessionStorage.getItem(k)) window.sessionStorage.setItem(k, value);\n      return window.sessionStorage.getItem(k);\n    } catch (e) {\n      return value;\n    }\n  }\n\n  function arrivingSrc() {\n    try {\n      var p = new URLSearchParams(window.location.search);\n      return p.get(\"src\") || null;\n    } catch (e) {\n      return null;\n    }\n  }\n\n  function init() {\n    var slug = pageSlug();\n    if (!slug) return;\n\n    /* Events 1, 2, and the card leg of Event 3: the partner card. */\n    var card = document.querySelector('article.partnercard[data-profile=\"renaud-naturals\"]');\n    if (card) {\n      var surface = card.getAttribute(\"data-surface\") || inferSurface(slug);\n\n      if (\"IntersectionObserver\" in window) {\n        var seen = false;\n        var io = new IntersectionObserver(function (entries) {\n          for (var i = 0; i < entries.length; i++) {\n            if (entries[i].isIntersecting && !seen) {\n              seen = true;\n              fire(\"/_events/renaud-card-view/\" + surface + \"/\" + slug);\n              io.disconnect();\n            }\n          }\n        }, { threshold: 0.5 });\n        io.observe(card);\n      }\n\n      card.addEventListener(\"click\", function (ev) {\n        var a = ev.target && ev.target.closest ? ev.target.closest(\"a\") : null;\n        if (!a) return;\n        var h = a.getAttribute(\"href\") || \"\";\n        if (h.indexOf(\"tel:\") === 0) {\n          fire(\"/_events/renaud-call/\" + surface + \"/\" + slug);\n          return;\n        }\n        if (h.indexOf(\"/natural-skincare/renaud-naturals-loveland/\") === 0) {\n          firstTouchSrc(surface);\n          fire(\"/_events/renaud-card-click/\" + surface + \"/\" + slug);\n        }\n      });\n    }\n\n    /* Profile page bindings: Event 3 profile leg and S2 website outbound. */\n    if (slug === PROFILE_SLUG) {\n      var src = arrivingSrc();\n      if (src) firstTouchSrc(src);\n      document.addEventListener(\"click\", function (ev) {\n        var a = ev.target && ev.target.closest ? ev.target.closest(\"a\") : null;\n        if (!a) return;\n        var h = a.getAttribute(\"href\") || \"\";\n        if (a.hasAttribute(\"data-renaud-call\") || h.indexOf(\"tel:+19706671433\") === 0) {\n          fire(\"/_events/renaud-call/ytp-profile/\" + slug);\n          return;\n        }\n        if (a.hasAttribute(\"data-renaud-website\") || h.indexOf(\"https://renaudnaturals.com\") === 0) {\n          fire(\"/_events/renaud-website/ytp-profile/\" + slug);\n        }\n      });\n    }\n  }\n\n  if (document.readyState === \"loading\") {\n    document.addEventListener(\"DOMContentLoaded\", init);\n  } else {\n    init();\n  }\n})();\n\n</script>";
